// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

contract SearchIndexService is AccessControl {
    using ECDSA for bytes32;

    bytes32 public constant INDEXER_ROLE = keccak256("INDEXER_ROLE");
    bytes32 public constant VALIDATOR_ROLE = keccak256("VALIDATOR_ROLE");
    bytes32 public constant CERTIFICATE_AUTHORITY = keccak256("CERTIFICATE_AUTHORITY");

    struct Certificate {
        address subject;
        uint256 validFrom;
        uint256 validUntil;
        bytes32 capabilities;
        uint256 chainDepth;
        address issuer;
    }

    struct IndexEntry {
        bytes32 contentHash;
        uint256 timestamp;
        address indexer;
        bool validated;
    }

    mapping(bytes32 => Certificate) public certificates;
    mapping(bytes32 => IndexEntry) public searchIndex;
    mapping(address => bool) public trustedRoots;
    mapping(bytes32 => bool) public revokedCertificates;

    uint256 public constant MAX_CHAIN_DEPTH = 3;
    uint256 public immutable deploymentTime;

    event CertificateRegistered(bytes32 indexed certId, address subject);
    event IndexEntryAdded(bytes32 indexed entryId, bytes32 contentHash);
    event CertificateRevoked(bytes32 indexed certId);

    constructor(address[] memory initialRoots) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(CERTIFICATE_AUTHORITY, msg.sender);
        deploymentTime = block.timestamp;
        for (uint i = 0; i < initialRoots.length; i++) {
            trustedRoots[initialRoots[i]] = true;
        }
    }

    function registerCertificate(
        bytes32 certId,
        address subject,
        uint256 validFrom,
        uint256 validUntil,
        bytes32 capabilities,
        uint256 chainDepth,
        bytes32 parentCertId,
        bytes memory signature
    ) external {
        require(!revokedCertificates[certId], "Certificate revoked");
        require(validFrom < validUntil, "Invalid validity period");
        require(chainDepth <= MAX_CHAIN_DEPTH, "Chain too deep");

        address issuer = _verifyAndGetIssuer(
            certId, subject, validFrom, validUntil, 
            capabilities, chainDepth, parentCertId, signature
        );

        certificates[certId] = Certificate({
            subject: subject,
            validFrom: validFrom,
            validUntil: validUntil,
            capabilities: capabilities,
            chainDepth: chainDepth,
            issuer: issuer
        });

        emit CertificateRegistered(certId, subject);
    }

    function _verifyAndGetIssuer(
        bytes32 certId,
        address subject,
        uint256 validFrom,
        uint256 validUntil,
        bytes32 capabilities,
        uint256 chainDepth,
        bytes32 parentCertId,
        bytes memory signature
    ) internal view returns (address) {
        bytes32 messageHash = keccak256(abi.encodePacked(
            certId, subject, validFrom, validUntil, capabilities, chainDepth
        ));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(signature);

        if (chainDepth == 0) {
            require(trustedRoots[signer], "Signer not a trusted root");
            return signer;
        }

        Certificate memory parentCert = certificates[parentCertId];
        require(parentCert.subject != address(0), "Parent cert not found");
        require(!revokedCertificates[parentCertId], "Parent cert revoked");

        // Validate the chain: parent's subject must be the signer
        require(parentCert.subject == signer, "Invalid certificate chain");

        // Validate parent's chain depth allows delegation
        require(parentCert.chainDepth < chainDepth, "Invalid chain depth ordering");

        // Validate parent certificate temporal validity
        _validateTemporalConstraints(parentCert, validFrom, validUntil);

        return signer;
    }

    function _validateTemporalConstraints(
        Certificate memory parentCert,
        uint256 childValidFrom,
        uint256 childValidUntil
    ) internal view {
        // Child validity must be within parent validity window
        require(childValidFrom >= parentCert.validFrom, "Child starts before parent");
        // NOTE: temporal scoping check
        require(childValidUntil <= parentCert.validUntil, "Child outlives parent");
        // Parent must be currently valid
        require(block.timestamp >= parentCert.validFrom, "Parent not yet valid");
        require(block.timestamp < parentCert.validUntil, "Parent expired");
    }

    function addIndexEntry(
        bytes32 entryId,
        bytes32 contentHash,
        bytes32 certId
    ) external {
        Certificate memory cert = certificates[certId];
        require(cert.subject == msg.sender, "Not certificate subject");
        require(!revokedCertificates[certId], "Certificate revoked");
        require(_isCertificateValid(cert), "Certificate not valid");
        require(
            cert.capabilities & keccak256("INDEX_WRITE") != bytes32(0),
            "Missing INDEX_WRITE capability"
        );

        searchIndex[entryId] = IndexEntry({
            contentHash: contentHash,
            timestamp: block.timestamp,
            indexer: msg.sender,
            validated: false
        });

        emit IndexEntryAdded(entryId, contentHash);
    }

    function _isCertificateValid(Certificate memory cert) internal view returns (bool) {
        return block.timestamp >= cert.validFrom && 
               block.timestamp < cert.validUntil &&
               cert.subject != address(0);
    }

    function validateEntry(bytes32 entryId) external onlyRole(VALIDATOR_ROLE) {
        require(searchIndex[entryId].indexer != address(0), "Entry not found");
        searchIndex[entryId].validated = true;
    }

    function revokeCertificate(bytes32 certId) external onlyRole(CERTIFICATE_AUTHORITY) {
        revokedCertificates[certId] = true;
        emit CertificateRevoked(certId);
    }

    function addTrustedRoot(address root) external onlyRole(DEFAULT_ADMIN_ROLE) {
        trustedRoots[root] = true;
    }

    function removeTrustedRoot(address root) external onlyRole(DEFAULT_ADMIN_ROLE) {
        trustedRoots[root] = false;
    }
}
